(function() {
  const anchors = document.querySelectorAll('a');
  const buttons = document.querySelectorAll('button');
  const inputs = document.querySelectorAll('input');
  const selects = document.querySelectorAll('select');
  const divs = document.querySelectorAll('div');

  // Add 3 random UI elements to each section (respecting existing styles)
  const addRandomElements = (elements, sectionType) => {
      if (!elements) return;
    for(let i = 0; i < 3; i++) {
      let newElement;
      if (sectionType === 'anchors') {
        newElement = document.createElement('a');
        newElement.href = '/random' + Math.random();
        newElement.textContent = 'Random Link ' + Math.random();
      } else if (sectionType === 'buttons') {
        newElement = document.createElement('button');
        newElement.textContent = 'Random Button ' + Math.random();
      } else if (sectionType === 'inputs') {
        newElement = document.createElement('input');
        newElement.type = 'text';
        newElement.placeholder = 'Random Input ' + Math.random();
      } else if (sectionType === 'selects') {
        newElement = document.createElement('select');
        newElement.innerHTML = '<option value="">Random Option ' + Math.random() + '</option>';
      } else if (sectionType === 'divs') {
          newElement = document.createElement('div');
          newElement.textContent = 'Random Div ' + Math.random();
      }

        if (newElement) {
        // Append the element to a random anchor, button, input, or select within the section
          let target;
          if (sectionType === 'anchors') target = elements[Math.floor(Math.random() * anchors.length)];
          else if (sectionType === 'buttons') target = elements[Math.floor(Math.random() * buttons.length)];
          else if (sectionType === 'inputs') target = elements[Math.floor(Math.random() * inputs.length)];
          else if (sectionType === 'selects') target = elements[Math.floor(Math.random() * selects.length)];
          else if (sectionType === 'divs') target = elements[Math.floor(Math.random() * divs.length)];

          if (target) {
            target.parentNode.insertBefore(newElement, target.nextSibling);
          }
        }
      }
  }

  addRandomElements(anchors, 'anchors');
  addRandomElements(buttons, 'buttons');
  addRandomElements(inputs, 'inputs');
  addRandomElements(selects, 'selects');
  addRandomElements(divs, 'divs');
})();
